      (ok ? ' · <b class="pass">PASS</b>' : ' · <b class="fail">FAIL</b> — implied mismatches: ' + esc(bad.slice(0, 5).join(', ')) + (evBad.length ? '; EV mismatches: ' + esc(evBad.slice(0, 5).join(', ')) : ''));
