      if (!k) return;
      if (state.sort === k) state.dir *= -1;
      else { state.sort = k; state.dir = (k === 'rank' || k === 'implied_value_usd' || k === 'expected_value_usd' || k === 'odds' || k === 'tvl_usd' || k === 'multiple') ? -1 : 1; }
      $('sort').value = state.sort;
      syncUrl(); render();
    });
  });
