  $('sort').addEventListener('change', function () {
    state.sort = $('sort').value;
    state.dir = (state.sort === 'rank' || state.sort === 'implied_value_usd' || state.sort === 'expected_value_usd' || state.sort === 'odds' || state.sort === 'tvl_usd') ? -1 : 1;
    syncUrl(); render();
